from pathlib import Path
import base64,json,html,re
root=Path(__file__).resolve().parents[1];ev=root/'docs/profile-products-lots8-9/evidence';out=root.parent/'deliverables/NailMoods-Lots8-9';out.mkdir(parents=True,exist_ok=True)
results=json.loads((ev/'browser-lots89.json').read_text());assert results['passed']
testlog=Path('/tmp/nm89-tests.log').read_text();counts={k:int(re.search('ℹ '+k+' (\\d+)',testlog).group(1)) for k in ['tests','pass','fail','skipped']};assert counts['fail']==0;(ev/'tests-summary.json').write_text(json.dumps(counts,indent=2))
def img(name,alt):return '<img loading="lazy" alt="'+html.escape(alt)+'" src="data:image/png;base64,'+base64.b64encode((ev/name).read_bytes()).decode()+'">'
